public async Task<IReadOnlyList<User>> GetActiveUsersAsync(CancellationToken ct = default)
    => await _dbContext.Users
        .AsNoTracking()
        .Where(u => u.IsActive)
        .ToListAsync(ct);

if (user is not null)
{
